#!/usr/bin/env python3
"""Print every arcane-cli command path, one per line, by walking `--help`.

Usage: scripts/dump_cli_commands.py [path-to-arcane-cli] > tests/fixtures/cli-commands.txt
Prints the header line for the CLI's own version, then the sorted command paths.
"""

import re
import subprocess
import sys

# `help` and `completion` are generated by the CLI framework, not Arcane commands.
SKIP = {"help", "completion"}
ANSI = re.compile(r"\x1b\[[0-9;]*m")


def run(cli: str, *args: str) -> str:
    out = subprocess.run([cli, *args], capture_output=True, text=True, check=True, timeout=30)
    return ANSI.sub("", out.stdout)


def children(cli: str, path: tuple[str, ...]) -> list[tuple[str, bool]]:
    """Subcommands of `path` as (name, has_children); only `name [command]` entries have children."""
    names, in_commands = [], False
    for line in run(cli, *path, "--help").splitlines():
        stripped = line.strip()
        if stripped == "COMMANDS":
            in_commands = True
        elif stripped.isupper() and stripped.isalpha():
            in_commands = False
        elif in_commands and stripped:
            name = stripped.split()[0]
            if name not in SKIP:
                names.append((name, "[command]" in stripped.split()))
    return names


def walk(cli: str, path: tuple[str, ...] = ()) -> list[tuple[str, ...]]:
    found = []
    for name, has_children in children(cli, path):
        child = (*path, name)
        found.append(child)
        if has_children:
            found.extend(walk(cli, child))
    return found


def main() -> None:
    cli = sys.argv[1] if len(sys.argv) > 1 else "arcane-cli"
    version = re.search(r"\d+\.\d+\.\d+\S*", run(cli, "--version")).group(0)
    print(f"# arcane-cli v{version} command paths (one per line). Regenerate when bumping ARCANE_CLI_VERSION:")
    print("# see README > Upgrading the pinned CLI.")
    for path in sorted(walk(cli)):
        print(" ".join(path))


if __name__ == "__main__":
    main()
